require_once __DIR__.'/../app/bootstrap_financial.php';requirePermission('kyc.manage');$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT id_file_path FROM id_verifications WHERE user_id=?');$stmt->execute([$id]);$relative=$stmt->fetchColumn();if(!$relative){http_response_code(404);exit('Document not found.');}$uploads=realpath(__DIR__.'/../uploads');$path=realpath(__DIR__.'/../'.ltrim((string)$relative,'/\\'));if(!$uploads||!$path||!str_starts_with($path,$uploads.DIRECTORY_SEPARATOR)||!is_file($path)){http_response_code(404);exit('Document not found.');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['image/jpeg','image/png','application/pdf'],true)){http_response_code(415);exit('Unsupported document type.');}audit($pdo,'kyc.document_viewed','user',$id);header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="verification-document.'.($mime==='application/pdf'?'pdf':($mime==='image/png'?'png':'jpg')).'"');header('X-Content-Type-Options: nosniff');readfile($path);
